rampas = ({
  divergente: () =&gt; [tok("--atl-div-neg-3"), tok("--atl-div-neg-2"), tok("--atl-div-neg-1"), tok("--atl-div-mid"),
                     tok("--atl-div-pos-1"), tok("--atl-div-pos-2"), tok("--atl-div-pos-3")],
